26: export async function invokeHostedProgramAssessment({ operation, modelInput }, options, dependencies = {}) {
27:   modelInput = structuredClone(modelInput);
28:   options = { ...options, executionModel: options.executionModel === undefined
29:     ? undefined : structuredClone(options.executionModel),
30:     registeredModelRefs: options.registeredModelRefs ? [...options.registeredModelRefs] : undefined };
31:   validateJobAidProblemInput(modelInput);
32:   const checkpoint = options.assessmentCheckpoint;
33:   if (operation !== 'EVALUATE_JOBAID' || modelInput.executionMode !== PROGRAM_ASSESSMENT_MODE ||
34:       modelInput.purpose !== 'INITIAL_PROBLEM_ASSESSMENT' || !checkpoint ||
35:       !options.sessionDiscriminator || typeof options.readAssessmentSources !== 'function' ||
36:       typeof options.readAssessmentWork !== 'function' || typeof options.saveAssessmentWork !== 'function' ||
37:       typeof options.recordAssessmentProgramProgress !== 'function') throw new Error('PROGRAM_ASSESSMENT_CAPABILITY_REQUIRED');
38:   assertHostedModelGatewayReady(options);
39:   const usesCodex = modelExecutor(options) === 'CODEX';
40:   const hostBinding = options.assessmentBinding;
41:   if (usesCodex && (!hostBinding ||
42:       ['attemptRef', 'actionAttemptId', 'workItemId', 'documentVersionId'].some(key =>
43:         typeof hostBinding[key] !== 'string' || !hostBinding[key].trim()) ||
44:       !Number.isSafeInteger(hostBinding.baseRevision) || hostBinding.baseRevision < 0))
45:     throw new Error('PROGRAM_ASSESSMENT_HOST_BINDING_REQUIRED');
46:   const codexRecoveryRequestId = usesCodex ? `program:${hostBinding.attemptRef}:round-1` : null;
47:   const modelHeaders = executionModelHeaders(options);
48:   const binding = { operation, modelInput, sessionDiscriminator: options.sessionDiscriminator,
49:     executionModel: options.executionModel ?? null,
50:     ...(usesCodex ? { modelExecutor: 'CODEX', assessmentBinding: hostBinding } : {}) };
51:   const retainedParentResult = usesCodex && options.reconcileProgramModelRequest
52:     ? await checkpoint.readOptional('assessment-round-1.result') : null;
53:   let enabled = await checkpoint.readOptional('assessment-enabled');
54:   if (retainedParentResult && !enabled) throw new Error('PROGRAM_ASSESSMENT_RESPONSE_BINDING_MISMATCH');
