56:     throw new Error('PROGRAM_ASSESSMENT_CHECKPOINT_BINDING_MISMATCH');
57:   if (!enabled) {
58:     enabled = { version: 2, binding, startedAt: Date.now(), generationPolicy: POLICY };
59:     await checkpoint.writeOnce('assessment-enabled', enabled);
60:   }
61:   if (!await checkpoint.readOptional('assessment-state')) await checkpoint.writeOnce('assessment-state', {
62:     round: 1, protocolRepairs: 0, noProgressRepairs: 0, executionMode: PROGRAM_ASSESSMENT_MODE,
63:   });
64:   const previousExecution = await checkpoint.readOptional('program-execution');
65:   if (previousExecution) return previousExecution;
66:   let materials = await checkpoint.readOptional('program-materials');
67:   if (retainedParentResult && !materials) throw new Error('PROGRAM_ASSESSMENT_MATERIALS_BINDING_MISMATCH');
68:   if (!materials) {
69:     materials = await prepareProgramAssessmentMaterials(modelInput, options);
70:     await checkpoint.writeOnce('program-materials', materials);
71:     materials = await checkpoint.readOptional('program-materials');
72:   }
73:   if (!materials || !isDeepStrictEqual(materials.originalInput, modelInput))
74:     throw new Error('PROGRAM_ASSESSMENT_MATERIALS_BINDING_MISMATCH');
75:   const recordProgress = async (phase, key, materialSnapshotJson) => {
