2214: async function createJobAidRunBudget(checkpoint, limits, hasBinding, selection) {
2215:   const step = 'jobaid-run-budget';
2216:   let state = await checkpoint.readOptional(step);
2217:   if (!limits && !state) return null;
2218:   if (!limits) throw new Error('JOBAID_RUN_LIMIT_REQUIRED');
2219:   limits = { ...limits };
2220:   if (!state) {
2221:     if (hasBinding) throw new Error('JOBAID_RUN_LIMIT_LEGACY_CHECKPOINT');
2222:     state = { limits, counts: { modelRequests: 0, saves: 0, finishes: 0 }, active: null,
2223:       ...(selection ? { explicitOnly: true, selection } : {}) };
2224:     await checkpoint.writeOnce(step, state);
2225:   } else if (!isDeepStrictEqual(state.limits, limits) ||
2226:       Object.keys(limits).some(key => !Number.isSafeInteger(state.counts?.[key]) ||
2227:         state.counts[key] < 0 || state.counts[key] > limits[key]) ||
2228:       (state.active !== null && !Object.hasOwn(limits, state.active?.kind))) {
2229:     throw new Error('JOBAID_RUN_LIMIT_CHECKPOINT_CHANGED');
2230:   }
2231:   if (selection && !isDeepStrictEqual(state.selection, selection))
2232:     throw new Error('JOBAID_RUN_LIMIT_SELECTION_CHANGED');
2233:   const complete = async () => {
2234:     const completed = { ...state, active: null };
2235:     await checkpoint.write(step, completed);
2236:     state = completed;
2237:   };
2238:   return {
2239:     snapshot: () => ({ limits: { ...state.limits }, dispatchReservations: { ...state.counts },
2240:       pendingOutcome: state.active?.kind ?? null, upstreamDispatchCount: null }),
2241:     dispatch: async (kind, perform, args = {}) => {
2242:       if (state.active) throw new Error('JOBAID_RUN_OUTCOME_UNKNOWN');
2243:       if (state.counts[kind] >= limits[kind]) {
2244:         const label = kind === 'modelRequests' ? 'MODEL_HTTP' : kind === 'saves' ? 'SAVE' : 'FINISH';
2245:         throw new Error(`JOBAID_${label}_BUDGET_EXHAUSTED`);
2246:       }
2247:       // Exclusive existing checkpoint writes also stop competing consumers
2248:       // from reserving the same ordinal before either dispatches.
2249:       await checkpoint.writeOnce(`${step}-${kind}-${state.counts[kind] + 1}`, {
2250:         kind, ordinal: state.counts[kind] + 1,
2251:       });
2252:       state = { ...state, counts: { ...state.counts, [kind]: state.counts[kind] + 1 },
2253:         active: { kind, ...(kind === 'saves' ? { requestId: args.requestId } : {}),
2254:           ...(kind === 'finishes' ? { attemptRef: args.attemptRef, contentHash: args.result?.contentHash } : {}) } };
2255:       await checkpoint.write(step, state);
2256:       let value;
2257:       try { value = await perform(); }
2258:       catch (error) {
2259:         // Host materializes requirementHandling before work.save. This exact
2260:         // received validation rejection is a known non-write, still charged
2261:         // against the SAVE cap. Other Host errors may follow a committed write.
2262:         if (kind === 'saves' && error?.receivedHostToolError === true &&
2263:             error.hostToolName === 'save_assessment_work' &&
2264:             error.hostErrorCode === 'JOBAID_REQUIREMENTS_INVALID') await complete();
2265:         throw error;
2266:       }
2267:       await complete();
2268:       return value;
2269:     },
2270:     reconcile: async (name, value) => {
2271:       const active = state.active;
2272:       if ((name === 'read_assessment_work' && active?.kind === 'saves' &&
2273:           typeof active.requestId === 'string' && value?.revision?.requestId === active.requestId) ||
2274:           (name === 'get_action_attempt_status' && active?.kind === 'finishes' &&
2275:           typeof active.contentHash === 'string' && value?.attemptRef === active.attemptRef &&
2276:           value?.resultContentHash === active.contentHash && ['SUCCEEDED', 'WAITING_INPUT', 'FAILED'].includes(value?.status)))
2277:         await complete();
2278:     },
2279:     reconcileProgramModelRequest: async verifyOriginalResponse => {
2280:       if (state.active?.kind !== 'modelRequests') return;
2281:       if (state.counts.modelRequests !== 1 ||
2282:           !isDeepStrictEqual(state.active, { kind: 'modelRequests' }) ||
2283:           !isDeepStrictEqual(await checkpoint.readOptional(`${step}-modelRequests-1`),
2284:             { kind: 'modelRequests', ordinal: 1 }))
2285:         throw new Error('JOBAID_PROGRAM_MODEL_BUDGET_RECOVERY_INVALID');
2286:       // This trusted program callback verifies the original local Codex run.
2287:       // No new dispatch, reservation, refund or Host authority is created.
2288:       await verifyOriginalResponse();
2289:       await complete();
2290:     },
2291:   };
